style.css:
@-moz-document domain("roblox.com") {
.btn-primary-lg, 
    .btn-primary-md, 
    .btn-primary-sm,
    .btn-growth-lg,
    .btn-growth-md,
    .btn-growth-sm,
    .btn-full-width {
        background-color: #ffc0cb !important;
        border-color: #f4a6b6 !important;
        color: #ffffff !important;
        border-radius: 8px !important;
        transition: background-color 0.2s ease, border-color 0.2s ease !important;
    }

    .btn-primary-lg:hover, 
    .btn-primary-md:hover, 
    .btn-primary-sm:hover,
    .btn-growth-lg:hover,
    .btn-growth-md:hover,
    .btn-growth-sm:hover,
    .btn-full-width:hover {
        background-color: #bae6fd !important;
        border-color: #7dd3fc !important;
        color: #ffffff !important;
    }

    .btn-secondary-lg,
    .btn-secondary-md,
    .btn-secondary-sm,
    .btn-control-lg,
    .btn-control-md,
    .btn-control-sm {
        background-color: #ffffff !important;
        border: 2px solid #ffb7c5 !important;
        color: #e879f9 !important;
        border-radius: 8px !important;
        transition: all 0.2s ease !important;
    }

    .btn-secondary-lg:hover,
    .btn-secondary-md:hover,
    .btn-secondary-sm:hover,
    .btn-control-lg:hover,
    .btn-control-md:hover,
    .btn-control-sm:hover {
        background-color: #e0f2fe !important;
        color: #0284c7 !important;
    }

    .btn-common-play-game-lg {
        background-color: #ffd1dc !important;
        border-color: #f4a6b6 !important;
    }

    .btn-common-play-game-lg:hover {
        background-color: #b9e6fe !important;
        border-color: #7dd3fc !important;
    }
}
